import { atom, read, update } from 'claude-code'
import type { Color, EngineInterface, Register, SessionUsage } from 'claude-code'

import type { Limit, Reading, Tokens } from '../types'

const ZERO: Tokens = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }
const EMPTY: Reading = { limits: [] }
const tokens = atom({ plugin: 'usage-meter', key: 'tokens' } as const, ZERO)
const reading = atom({ plugin: 'usage-meter', key: 'reading' } as const, EMPTY)

const LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d', spend_limit: 'spend' }

export const label = (kind: string): string => LABELS[kind] ?? kind

export const compact = (n: number): string =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${(n / 1e3).toFixed(1)}k` : `${n}`

export const severity = (percent: number): Color | undefined =>
  percent >= 90 ? 'error' : percent >= 70 ? 'warning' : undefined

const toReading = (u: Omit<SessionUsage, 'startedAt'>): Reading => ({
  contextPercent: u.context.percent,
  limits: u.rateLimits.map(({ kind, percentUsed }): Limit => ({ kind, percentUsed })),
  usd: u.cost?.usd,
})

async function refresh($: EngineInterface): Promise<void> {
  const usage = await $.session.usage()
  await update($, reading, () => toReading(usage))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await refresh($)
    return r
  })

  on('turn.complete', async ($, e, next) => {
    const u = e.usage
    if (u) {
      await update($, tokens, (t = ZERO) => ({
        input: t.input + u.input_tokens,
        output: t.output + u.output_tokens,
        cacheRead: t.cacheRead + u.cache_read_input_tokens,
        cacheWrite: t.cacheWrite + u.cache_creation_input_tokens,
      }))
    }
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await update($, reading, () => toReading(e))
    if (e.changed.includes('rateLimits')) {
      for (const r of e.rateLimits.filter(r => r.percentUsed >= 90)) {
        $.ui.toast(`Usage limit: ${label(r.kind)} window at ${r.percentUsed}%`)
      }
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) {
      return next(e)
    }

    const t = await read($, tokens)
    const r = await read($, reading)
    const { Box, Text } = $.ui.resolve(e)
    const sep = <Text dimColor>{'  ·  '}</Text>

    return (
      <Box flexDirection="row">
        <Text color="claude">{'📊 '}</Text>
        <Text bold>usage-meter</Text>
        <Text>{'  '}</Text>
        <Text dimColor>tokens </Text>
        <Text bold>
          {compact(t.input + t.output + t.cacheRead + t.cacheWrite)}
        </Text>
        <Text dimColor>
          {` (in ${compact(t.input + t.cacheRead + t.cacheWrite)} / out ${compact(t.output)})`}
        </Text>
        {r.contextPercent !== undefined && sep}
        {r.contextPercent !== undefined && <Text dimColor>ctx </Text>}
        {r.contextPercent !== undefined && (
          <Text bold color={severity(r.contextPercent)}>
            {`${r.contextPercent}%`}
          </Text>
        )}
        {r.limits.map(l => (
          <Box key={`limit-${l.kind}`} flexDirection="row">
            {sep}
            <Text dimColor>{`${label(l.kind)} `}</Text>
            <Text bold color={severity(l.percentUsed)}>
              {`${l.percentUsed}%`}
            </Text>
          </Box>
        ))}
        {r.usd !== undefined && sep}
        {r.usd !== undefined && (
          <Text bold>
            {`$${r.usd.toFixed(2)}`}
          </Text>
        )}
      </Box>
    )
  })
}

